void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    if (n == 0) {
        output.clear();
        return;
    }

    // Handle the case where input and output are the same vector object.
    const std::vector<double>* input = &x;
    std::vector<double> x_copy;
    if (reinterpret_cast<const void*>(&x) == reinterpret_cast<const void*>(&output)) {
        x_copy = x;
        input = &x_copy;
    }

    output.resize(n);

    int num_threads = 1;
    std::vector<double> block_sums;
    std::vector<double> block_offsets;

